package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.View;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Backend-aware bulk card operations. Every mutation re-reads and uses the selected .id. */
public final class CardOperationsActivity extends Activity {private Spinner backend;private EditText search;private ListView list;private TextView status;private final ArrayList<Map<String,String>> rows=new ArrayList<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean busy;private final int BLUE=Color.rgb(23,103,177),NAVY=Color.rgb(22,47,80);@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(16,18,16,28);p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);p.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(p);setContentView(s); UiTheme.apply(this);backend=new Spinner(this);backend.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Hotspot","User Manager v6","User Manager v7"}));p.addView(backend);search=new EditText(this);search.setHint("بحث بالاسم أو الباقة");p.addView(search);status=text("جاري التحميل",14);p.addView(status);list=new ListView(this);list.setChoiceMode(ListView.CHOICE_MODE_MULTIPLE);p.addView(list,new LinearLayout.LayoutParams(-1,620));Button refresh=button("تحديث",BLUE);refresh.setOnClickListener(v->load());p.addView(refresh);Button disable=button("تعطيل المحدد",BLUE);disable.setOnClickListener(v->mutate("disable"));p.addView(disable);Button enable=button("تفعيل المحدد",BLUE);enable.setOnClickListener(v->mutate("enable"));p.addView(enable);Button delete=button("حذف المحدد بعد التأكيد",Color.rgb(180,55,70));delete.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("تأكيد الحذف").setMessage("سيُحذف المحدد فقط باستخدام .id. لا يمكن التراجع.").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(d,w)->mutate("delete")).show());p.addView(delete);backend.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?>a,View v,int pos,long id){load();}});load();}
 private void load(){worker.execute(()->{try{String be=backend.getSelectedItem().toString();String ver=be.contains("v6")?"6.":be.contains("v7")?"7.":"";android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);String pw=new SecureConnectionStore(this).get();try(RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false))){r.login(p.getString("user",""),pw==null?"":pw);List<Map<String,String>> x=be.startsWith("Hotspot")?new HotspotService(r).users():new UserManagerService(r).users(ver);synchronized(rows){rows.clear();rows.addAll(x);}ui(()->render());}}catch(Exception e){ui(()->status.setText("فشل القراءة: "+safe(e)));}});}
 private void render(){ArrayList<String> labels=new ArrayList<>();String q=search.getText().toString().toLowerCase(Locale.ROOT);for(Map<String,String> m:rows){String v=m.getOrDefault("name",m.getOrDefault("username",""))+" | "+m.getOrDefault("profile","")+" | "+( "true".equalsIgnoreCase(m.get("disabled"))?"معطل":"فعال");if(q.isEmpty()||v.toLowerCase(Locale.ROOT).contains(q))labels.add(v);}list.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_multiple_choice,labels));status.setText("تم تحميل "+labels.size()+" كرت");}
 private void mutate(String action){if(busy)return;ArrayList<String> ids=new ArrayList<>();for(int i=0;i<list.getCount()&&i<rows.size();i++)if(list.isItemChecked(i))ids.add(rows.get(i).get(".id"));if(ids.isEmpty()){status.setText("حدد كرتًا واحدًا على الأقل");return;}busy=true;worker.execute(()->{int ok=0;try{String be=backend.getSelectedItem().toString();String ver=be.contains("v6")?"6.":"7.";android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);String pw=new SecureConnectionStore(this).get();try(RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false))){r.login(p.getString("user",""),pw==null?"":pw);if(be.startsWith("Hotspot")){HotspotService x=new HotspotService(r);List<Map<String,String>> fresh=x.users();for(String id:ids){Map<String,String> row=MutationGuard.requireId(fresh,id);if("delete".equals(action))x.removeUser(id);else x.setDisabled(id,"disable".equals(action));ok++;}}else{UserManagerService x=new UserManagerService(r);List<Map<String,String>> fresh=x.users(ver);for(String id:ids){MutationGuard.requireId(fresh,id);if("delete".equals(action))x.removeUser(ver,id);else x.setDisabled(ver,id,"disable".equals(action));ok++;}}}final int done=ok;ui(()->{busy=false;status.setText("تم تنفيذ "+done+" من "+ids.size()+"؛ حدّث القائمة للتحقق");load();});}catch(Exception e){final int failed=ok;ui(()->{busy=false;status.setText("توقف التنفيذ بعد "+failed+": "+safe(e));});}});}
 private Button button(String s,int c){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(c));return b;}private TextView text(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextColor(NAVY);t.setTextSize(z);t.setPadding(8,10,8,10);return t;}private String safe(Exception e){return e.getMessage()==null?"خطأ غير معروف":e.getMessage();}private void ui(Runnable r){runOnUiThread(r);}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}}
